class CurvingFevers extends Turtle {

   double speed = 5; 
   double turningspeed = 10; 

   CurvingFevers(int x, int y) {
      super(x, y, true);
   }

   void steuern(); 

   void crashPrüfen();

   public void act() {
      forward(speed);
      crashPrüfen(); 
      steuern(); 
   }

}

class Curver1 extends CurvingFevers {

   Curver1() {
      super(600, 500);
      setBorderColor(Color.aqua);
   }

   @Override
   void steuern() {
      if(isKeyDown("a")) {
         turn(speed);
      }
      if(isKeyDown("d")) {
         turn(-speed);
      }
   }

   @Override
   void crashPrüfen() {
      if(collidesWithBorderColor(Color.magenta)) {
         destroy();
         System.exit(0);
      }
   }

}

class Curver2 extends CurvingFevers {

   Curver2() {
      super(100, 100);
      setBorderColor(Color.magenta);
   }

   @Override
   void steuern() {
      if(isKeyDown(Key.ArrowLeft)) {
         turn(speed);
      }
      if(isKeyDown(Key.ArrowRight)) {
         turn(-speed);
      }
   }

   @Override
   void crashPrüfen() {
      if(collidesWithBorderColor(Color.aqua) || isOutsideView()) {
         destroy();
         System.exit(0);
      }
   }
}
